49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    private final TelephoneNormalizer telephoneNormalizer;
70	
71	    private final HouseholdNormalizer householdNormalizer;
72	
73	    private final AddressNormalizer addressNormalizer;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper,
79	                                 TelephoneNormalizer telephoneNormalizer,
80	                                 HouseholdNormalizer householdNormalizer,
81	                                 AddressNormalizer addressNormalizer) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	        this.telephoneNormalizer = telephoneNormalizer;
87	        this.householdNormalizer = householdNormalizer;
88	        this.addressNormalizer = addressNormalizer;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        normalizeOwnerFields(owner);
122	        // Reject creating an owner whose normalized telephone is already used by another owner.
123	        String normalizedTelephone = owner.getTelephone();
124	        if (isTelephoneInUse(normalizedTelephone)) {
125	            throw new DuplicateTelephoneException(
126	                "An owner with telephone " + normalizedTelephone + " already exists");
127	        }
128	        // Identify any existing owners who share a household (same last name and address,
129	        // compared case-insensitively with collapsed whitespace) with the owner being created.
130	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        // Reject creating an owner who shares a household with an existing owner, unless the
133	        // request explicitly opts in with 'sharesHousehold' true.
134	        if (!sharesHousehold && !householdMembers.isEmpty()) {
135	            throw new DuplicateHouseholdException(
136	                "An owner with the same last name and address already exists");
137	        }
138	        // When opting in and joining an existing household, assign the new owner and every
139	        // existing member the same stable household identifier derived from the last name and
140	        // address, so all owners of the household share one 'householdId'.
141	        if (sharesHousehold && !householdMembers.isEmpty()) {
142	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
143	            owner.setHouseholdId(householdId);
144	            for (Owner member : householdMembers) {
145	                if (!householdId.equals(member.getHouseholdId())) {
146	                    member.setHouseholdId(householdId);
147	                    this.clinicService.saveOwner(member);
148	                }
149	            }
150	        }
151	        // Assign the customer code '<LAST3>-<NNNN>' from the last name and a global sequence
152	        // equal to one more than the current number of owners, fixed at creation time.
153	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
154	        this.clinicService.saveOwner(owner);
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        headers.setLocation(UriComponentsBuilder.newInstance()
157	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
158	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
159	    }
160	
161	    /**
162	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
163	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
164	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
165	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
166	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
167	     * server's current date. Canonicalising the address here, before the household checks read it,
168	     * ensures duplicate detection and the shared household id both compare the normalized form.
169	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
170	     * duplicate, household and customer-code rules.
171	     *
172	     * @param owner the newly mapped owner to canonicalize
173	     */
174	    private void normalizeOwnerFields(Owner owner) {
175	        // Normalize the address on create so it is stored and returned in canonical form and every
176	        // later comparison (household duplicate detection and the shared household id) uses it.
177	        // A value that is blank after normalization is rejected with 400.
178	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
179	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
180	        // A value that cannot form a valid E.164 number is rejected with 400.
181	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
182	        // Store the (already syntactically validated) email lower-cased so it is persisted and
183	        // returned in canonical form. A missing email is left untouched.
184	        owner.setEmail(normalizeEmail(owner.getEmail()));
185	        // Default the registration date to the server's current date when the client did not
186	        // supply one, so it is persisted and returned in ISO 'YYYY-MM-DD' form.
187	        if (owner.getRegistrationDate() == null) {
188	            owner.setRegistrationDate(java.time.LocalDate.now());
189	        }
190	    }
191	
192	    /**
193	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
194	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
195	     * syntactically valid address (rejecting anything else with 400).
196	     *
197	     * @param email the email value (may be {@code null})
198	     * @return the lower-cased email, or {@code null} if the input was {@code null}
199	     */
200	    private String normalizeEmail(String email) {
201	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
202	    }
203	
204	    /**
205	     * Builds the customer code '<LAST3>-<NNNN>' for a newly created owner, where LAST3 is the
206	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
207	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
208	     *
209	     * @param lastName the owner's last name
210	     * @return the formatted customer code
211	     */
212	    private String nextCustomerCode(String lastName) {
213	        String prefix = lastName.substring(0, Math.min(3, lastName.length()))
214	            .toUpperCase(java.util.Locale.ROOT);
215	        int sequence = this.clinicService.findAllOwners().size() + 1;
216	        return String.format("%s-%04d", prefix, sequence);
217	    }
218	
219	    /**
220	     * Determines whether the given normalized telephone is already used by an existing owner.
221	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
222	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
223	     * as the same number.
224	     *
225	     * @param normalizedTelephone the normalized (E.164) telephone to look for
226	     * @return {@code true} if another owner already uses this telephone
227	     */
228	    private boolean isTelephoneInUse(String normalizedTelephone) {
229	        if (normalizedTelephone == null) {
230	            return false;
231	        }
232	        return this.clinicService.findAllOwners().stream()
233	            .map(Owner::getTelephone)
234	            .map(telephoneNormalizer::normalize)
235	            .anyMatch(normalizedTelephone::equals);
236	    }
237	
238	    /**
239	     * Returns the existing owners who share the given household, i.e. have the same last name and
240	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
241	     * differing only in letter case or in incidental whitespace are treated as the same household.
242	     *
243	     * @param lastName the last name of the owner being created
244	     * @param address  the address of the owner being created
245	     * @return the existing owners with a matching last name and address (possibly empty)
246	     */
247	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
248	        String householdKey = householdNormalizer.householdKey(lastName, address);
249	        return this.clinicService.findAllOwners().stream()
250	            .filter(existing -> householdNormalizer
251	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
252	            .toList();
253	    }
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
258	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
259	        if (currentOwner == null) {
260	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
261	        }
262	        currentOwner.setAddress(ownerFieldsDto.getAddress());
263	        currentOwner.setCity(ownerFieldsDto.getCity());
264	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
265	        currentOwner.setLastName(ownerFieldsDto.getLastName());
266	        // Normalize the telephone to canonical E.164 form so it is stored and returned
267	        // consistently with create; an unformattable value is rejected with 400.
268	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
269	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
270	        this.clinicService.saveOwner(currentOwner);
271	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
272	    }
273	
274	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
275	    @Transactional
276	    @Override
277	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
278	        Owner owner = this.clinicService.findOwnerById(ownerId);
279	        if (owner == null) {
280	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
281	        }
282	        this.clinicService.deleteOwner(owner);
283	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
284	    }
285	
286	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
287	    @Override
288	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
289	        Owner owner = this.clinicService.findOwnerById(ownerId);
290	        if (owner == null) {
291	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
292	        }
293	        HttpHeaders headers = new HttpHeaders();
294	        Pet pet = petMapper.toPet(petFieldsDto);
295	        owner.setId(ownerId);
296	        pet.setOwner(owner);
297	        pet.getType().setName(null);
298	        this.clinicService.savePet(pet);
299	        PetDto petDto = petMapper.toPetDto(pet);
300	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
301	            .buildAndExpand(pet.getId()).toUri());
302	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
303	    }
304	
305	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
306	    @Override
307	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
308	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
309	        if (currentOwner != null) {
310	            Pet currentPet = this.clinicService.findPetById(petId);
311	            if (currentPet != null) {
312	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
313	                currentPet.setName(petFieldsDto.getName());
314	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
315	                this.clinicService.savePet(currentPet);
316	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
317	            }
318	        }
319	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
320	    }
321	
322	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
323	    @Override
324	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
325	        HttpHeaders headers = new HttpHeaders();
326	        Visit visit = visitMapper.toVisit(visitFieldsDto);
327	        Pet pet = new Pet();
328	        pet.setId(petId);
329	        visit.setPet(pet);
330	        this.clinicService.saveVisit(visit);
331	        VisitDto visitDto = visitMapper.toVisitDto(visit);
332	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
333	            .buildAndExpand(visit.getId()).toUri());
334	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
335	    }
336	
337	
338	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
339	    @Override
340	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
341	        Owner owner = this.clinicService.findOwnerById(ownerId);
342	        if (owner != null) {
343	            Pet pet = owner.getPet(petId);
344	            if (pet != null) {
345	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
346	            }
347	        }
348	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
349	    }
350	}
